import { NextRequest, NextResponse } from "next/server";
import { put } from "@vercel/blob";
import { prisma } from "@/lib/prisma";

// TEMPORARY one-off route — deployed to run a production DB/Blob operation
// that can't be run from the local machine (broken local IPv6 route to
// Neon). Gated by a secret query param. Delete this file (and redeploy)
// immediately after a single successful use.
const SECRET = "e91b4a2f7c0d6e8a3b5f1d9c7a4e2b8f6d0c3a1e5b7d9f2c4a6e8b0d2f4a6c8e0";

const PHOTO_1 = ""; // תימני — smoother, moderate texture, medium oval
const PHOTO_2 = ""; // packaged lulav+hadas+arava+etrog bag — kids set ONLY
const PHOTO_6 = ""; // מרוקאי — smooth, elongated, clear pitom, deep gold when ripe
const PHOTO_7 = ""; // רגיל — knobby/bumpy surface, typical baladi look

const REGULAR_SLUGS = [
  "regular-kosher",
  "regular-mehadrin",
  "regular-mehadrin-min-hamehadrin",
  "regular-diamond",
];
const TEMANI_SLUGS = [
  "temani-kosher",
  "temani-mehadrin",
  "temani-mehadrin-min-hamehadrin",
  "temani-diamond",
];
const MOROCCAN_SLUGS = [
  "moroccan-kosher",
  "moroccan-mehadrin",
  "moroccan-mehadrin-min-hamehadrin",
  "moroccan-diamond",
];

const RANDOM_SET_CLAUSE =
  " הסט הפרטני נבחר באופן רנדומלי מתוך המלאי ברמת ההידור שנרכשה — לא אתרוג ספציפי לבחירה אישית.";

async function uploadOnce(pathname: string, base64: string, contentType: string) {
  const buffer = Buffer.from(base64, "base64");
  const blob = await put(pathname, buffer, { access: "public", contentType });
  return blob.url;
}

async function attachImageIfMissing(setId: string, url: string) {
  const existing = await prisma.setMedia.findFirst({ where: { setId, url } });
  if (existing) return false;
  const count = await prisma.setMedia.count({ where: { setId, type: "IMAGE" } });
  await prisma.setMedia.create({
    data: { setId, type: "IMAGE", url, sortOrder: count },
  });
  return true;
}

export async function GET(req: NextRequest) {
  const secret = req.nextUrl.searchParams.get("secret");
  if (secret !== SECRET) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  const log: string[] = [];

  // 1. Upload the 4 source images to Vercel Blob once each.
  const url1 = await uploadOnce(`sets/variety-refs/temani-${Date.now()}.jpg`, PHOTO_1, "image/jpeg");
  const url2 = await uploadOnce(`sets/variety-refs/kids-${Date.now()}.jpg`, PHOTO_2, "image/jpeg");
  const url6 = await uploadOnce(`sets/variety-refs/moroccan-${Date.now()}.jpg`, PHOTO_6, "image/jpeg");
  const url7 = await uploadOnce(`sets/variety-refs/regular-${Date.now()}.jpg`, PHOTO_7, "image/jpeg");
  log.push(`uploaded blobs: ${url1}, ${url2}, ${url6}, ${url7}`);

  // 2. Upsert the kids set.
  const kidsSet = await prisma.productSet.upsert({
    where: { slug: "kids-set" },
    update: {},
    create: {
      kind: "KIDS",
      slug: "kids-set",
      name: "סט ארבעת המינים לילדים (להתנסות)",
      etrogType: "סט לילדים",
      description:
        "סט קטן וחמוד לילדים, להחזקה, משחק והיכרות עם ארבעת המינים. הסט אינו כשר לברכה ואינו מיועד לקיום המצווה בפועל — מיועד להתנסות ולשמחת החג בלבד.",
      price: 3900,
      sortOrder: 1,
      active: true,
    },
  });
  log.push(`kids set id: ${kidsSet.id}`);

  // 3. Patch regular-set descriptions with the "random set" clause (idempotent).
  const allRegular = await prisma.productSet.findMany({ where: { kind: "REGULAR" } });
  for (const set of allRegular) {
    if (!set.description.includes("נבחר באופן רנדומלי")) {
      await prisma.productSet.update({
        where: { id: set.id },
        data: { description: set.description + RANDOM_SET_CLAUSE },
      });
      log.push(`patched description: ${set.slug}`);
    }
  }

  // 4. Attach variety-reference images.
  const attach = async (slugs: string[], url: string) => {
    for (const slug of slugs) {
      const set = await prisma.productSet.findUnique({ where: { slug } });
      if (!set) {
        log.push(`MISSING SLUG: ${slug}`);
        continue;
      }
      const added = await attachImageIfMissing(set.id, url);
      log.push(`${slug}: ${added ? "image attached" : "already had this image"}`);
    }
  };

  await attach(REGULAR_SLUGS, url7);
  await attach(TEMANI_SLUGS, url1);
  await attach(MOROCCAN_SLUGS, url6);
  await attachImageIfMissing(kidsSet.id, url2).then((added) =>
    log.push(`kids-set: ${added ? "image attached" : "already had this image"}`)
  );

  return NextResponse.json({ ok: true, log });
}
